SELECT id, title_id, version_no, status, change_type, change_summary, company_name, taxpayer_id, registered_address,
       phone, bank_name, bank_account, subject_ids_json, created_by, created_at
FROM invoice_title_version WHERE id = #{id}

SELECT id, title_id, version_no, status, change_type, change_summary, company_name, taxpayer_id,
       registered_address, phone, bank_name, bank_account, subject_ids_json, created_by, created_at
FROM invoice_title_version
WHERE title_id = #{titleId}
ORDER BY version_no DESC, id DESC
LIMIT #{pageSize} OFFSET #{offset}
